import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Notification from './components/Notification';
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import ProductDetail from './pages/ProductDetail';
import Cart from './pages/Cart';
import Dashboard from './pages/Dashboard';
import Favorites from './pages/Favorites';
import Checkout from './pages/Checkout';
import './App.css';

function App() {
  const [user, setUser] = useState(null);
  const [cart, setCart] = useState([]);
  const [notification, setNotification] = useState({ message: '', type: '' });

  useEffect(() => {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');
    if (token && userData) {
      const parsedUser = JSON.parse(userData);
      setUser(parsedUser);
      // Load user-specific cart
      const userCart = JSON.parse(localStorage.getItem(`cart_${parsedUser.id}`) || '[]');
      setCart(userCart);
    }
  }, []);

  useEffect(() => {
    // Save cart when it changes and user is logged in
    if (user) {
      localStorage.setItem(`cart_${user.id}`, JSON.stringify(cart));
    }
  }, [cart, user]);

  const showNotification = (message, type = 'info') => {
    setNotification({ message, type });
  };

  const hideNotification = () => {
    setNotification({ message: '', type: '' });
  };

  const addToCart = (product) => {
    setCart(prev => {
      const existing = prev.find(item => item._id === product._id);
      if (existing) {
        return prev.map(item => 
          item._id === product._id 
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    showNotification('Product added to cart!', 'success');
  };

  return (
    <Router>
      <div className="App">
        <Navbar user={user} setUser={setUser} cartCount={cart.length} />
        <Notification 
          message={notification.message} 
          type={notification.type} 
          onClose={hideNotification} 
        />
        <Routes>
          <Route path="/" element={<Home addToCart={addToCart} showNotification={showNotification} />} />
          <Route path="/login" element={<Login setUser={setUser} showNotification={showNotification} />} />
          <Route path="/register" element={<Register setUser={setUser} showNotification={showNotification} />} />
          <Route path="/product/:id" element={<ProductDetail addToCart={addToCart} showNotification={showNotification} />} />
          <Route path="/cart" element={<Cart cart={cart} setCart={setCart} showNotification={showNotification} />} />
          <Route path="/favorites" element={<Favorites addToCart={addToCart} showNotification={showNotification} />} />
          <Route path="/checkout" element={<Checkout showNotification={showNotification} />} />
          <Route path="/dashboard" element={<Dashboard user={user} showNotification={showNotification} />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
